// Operator is the platform entity: the syndication and investor-management
// layer, admitted by governance.
//
// An x/group account, and the requirement is not ceremony. An operator opens
// deals, decides they have closed, moves escrowed money to a drawdown account
// and attests that investors passed KYC. Each of those on a single key is one
// key away from a platform that takes money and does not invest it — and the
// investors here are precisely the people with no practical recourse, spread
// across jurisdictions, holding a position they cannot value.
type Operator struct {
	Address string `protobuf:"bytes,1,opt,name=address,proto3" json:"address,omitempty"`
	Name    string `protobuf:"bytes,2,opt,name=name,proto3" json:"name,omitempty"`
	// Where the platform entity itself operates from, which the proposal notes
	// is likely to be distinct from where the investee companies are based.
	Jurisdiction string `protobuf:"bytes,3,opt,name=jurisdiction,proto3" json:"jurisdiction,omitempty"`
	// Struck off operators keep their record. Every deal names the operator that
	// opened it, and "was this platform admitted at the time" has to stay
	// answerable long after somebody has stopped being admitted.
	Active     bool  `protobuf:"varint,4,opt,name=active,proto3" json:"active,omitempty"`
	AdmittedAt int64 `protobuf:"varint,5,opt,name=admitted_at,json=admittedAt,proto3" json:"admitted_at,omitempty"`
}

